steps.css:
body {
  font-family: Arial, sans-serif;
  text-align: center;
  background: #f7f5ff;
  color: #33304f;
}

.feld {
  display: inline-grid;
  place-items: center;
  width: 130px;
  height: 130px;
  margin: 8px;
  border-radius: 20px;
  background: #75b9ed;
  cursor: pointer;
}

.rot { background: #ff8e9e; }
.gruen { background: #90dbaa; }

button {
  display: block;
  margin: 20px auto;
  padding: 10px 18px;
  border: 0;
  border-radius: 10px;
  background: #504884;
  color: white;
  cursor: pointer;
}

